//! Generated, public client build metadata shared by native and WASM consumers.
//!
//! [`BUILD`] and every field of [`BuildMetadata`] are generated by this crate's
//! build script. Add public environment keys to its allowlist, not to this file.
//! Missing values are `None`; server-side secrets are never exported.
//!
//! ```
//! let _auth_base_url: Option<&str> = eg_build::BUILD.auth_base_url;
//! ```
//!
//! The `blocks` and `levels` features additionally expose the embedded
//! `BLOCKS_DIR` and `LEVELS_DIR` directories. Metadata-only consumers need neither.

include!(concat!(env!("OUT_DIR"), "/metadata.rs"));

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn generated_metadata_has_typed_optional_fields() {
        let _: &str = BUILD.build_env;
        let _: Option<&str> = BUILD.api_url;
        let _: Option<&str> = BUILD.publishable_key;
        let _: Option<&str> = BUILD.auth_base_url;
    }

    #[cfg(feature = "blocks")]
    #[test]
    fn embeds_builtin_blocks() {
        assert!(BLOCKS_DIR.files().next().is_some() || BLOCKS_DIR.dirs().next().is_some());
    }

    #[cfg(feature = "levels")]
    #[test]
    fn embeds_builtin_levels() {
        assert!(LEVELS_DIR.files().next().is_some() || LEVELS_DIR.dirs().next().is_some());
    }
}
